/*************************************/
/* NAME:	is_char_constant_valid     */
/* INPUT: 	a pointer to a token */
/* OUTPUT:      a BOOLEAN value      */
/*************************************/
static int is_char_constant_valid(str)
    token  str;
{
   return((*str) == '#' && isalpha(*(str+1)));
}

